'use client';
import { useState, useEffect } from 'react';
import { Stethoscope, Plus, Tag, Search, Filter, Building2 } from 'lucide-react';
import { useToast } from '@/context/ToastContext';

export default function ServiceManagement() {
  const [services, setServices] = useState([]);
  const [hospitals, setHospitals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);

  const { addToast } = useToast();

  // Form State
  const [formData, setFormData] = useState({
    hospital_id: '',
    name: '',
    category: 'Lab', // Default
    price: '',
    discount_price: '',
    description: ''
  });

  // Pagination State
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const LIMIT = 10;

  useEffect(() => {
    fetchServices(page);
    fetchHospitals();
  }, [page]); // Re-fetch on page change

  const fetchServices = async (currentPage = 1) => {
    setLoading(true);
    try {
      const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}/api/services?page=${currentPage}&limit=${LIMIT}`);
      if (res.ok) {
        const result = await res.json();
        // Handle both new paginated response and old array response (fallback)
        if (result.data) {
            setServices(result.data);
            setTotalPages(result.meta.totalPages);
        } else {
            setServices(result); // Fallback
        }
      }
    } catch (err) {
      console.error(err);
      addToast('Error fetching services', 'error');
    } finally {
      setLoading(false);
    }
  };

  const fetchHospitals = async () => {
      try {
        const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}/api/hospitals`);
        if (res.ok) {
          const data = await res.json();
          setHospitals(data);
        }
      } catch (err) {
        console.error(err);
      }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
        const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}/api/services`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(formData)
        });

        if (res.ok) {
            addToast('Service Added Successfully!', 'success');
            setShowForm(false);
            setFormData({ hospital_id: '', name: '', category: 'Lab', price: '', discount_price: '', description: '' });
            fetchServices(); 
        } else {
            addToast('Failed to add service', 'error');
        }
    } catch (err) {
        console.error(err);
        addToast('Error adding service', 'error');
    }
  };

  // Light & Clean Styles matching Dashboard
  const cardStyle = {
    background: '#fff',
    border: '1px solid #f0f0f0',
    borderRadius: '20px',
    boxShadow: '0 5px 20px rgba(0, 0, 0, 0.05)'
  };

  const inputStyle = {
    width: '100%', padding: '0.9rem', 
    background: '#F9FAFB', 
    border: '1px solid #E5E7EB', 
    color: '#333', borderRadius: '12px',
    outline: 'none', transition: 'border-color 0.2s',
    fontSize: '0.95rem'
  };

  if (showForm) {
      return (
          <div className="animate-fade-in">
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
                  <h1 style={{ fontSize: '2rem', fontWeight: '800', color: '#1C1C24' }}>Add New Service</h1>
                  <button className="btn" onClick={() => setShowForm(false)} style={{ background: 'transparent', border: '1px solid #ddd', color: '#666' }}>Cancel</button>
              </div>
              
              <div style={{ ...cardStyle, padding: '2.5rem', maxWidth: '700px', margin: '0 auto' }}>
                  <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                      
                      <div>
                          <label style={{ display: 'block', marginBottom: '0.6rem', color: '#64748b', fontSize: '0.9rem', fontWeight: '500' }}>Service Name</label>
                          <input 
                            type="text" required placeholder="e.g. MRI Scan, CBC Test"
                            value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})}
                            style={inputStyle}
                          />
                      </div>

                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem' }}>
                          <div>
                              <label style={{ display: 'block', marginBottom: '0.6rem', color: '#64748b', fontSize: '0.9rem', fontWeight: '500' }}>Category</label>
                              <select 
                                value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}
                                style={inputStyle}
                              >
                                  <option value="Lab">Lab Test</option>
                                  <option value="Scan">Scan / X-Ray</option>
                                  <option value="OPD">OPD Consultation</option>
                                  <option value="Surgery">Surgery</option>
                              </select>
                          </div>
                          <div>
                              <label style={{ display: 'block', marginBottom: '0.6rem', color: '#64748b', fontSize: '0.9rem', fontWeight: '500' }}>Assign To Hospital</label>
                              <select 
                                value={formData.hospital_id} onChange={e => setFormData({...formData, hospital_id: e.target.value})}
                                style={inputStyle}
                              >
                                  <option value="">-- Global / Independent --</option>
                                  {hospitals.map(h => (
                                      <option key={h.id} value={h.id}>{h.name}</option>
                                  ))}
                              </select>
                          </div>
                      </div>

                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem' }}>
                          <div>
                              <label style={{ display: 'block', marginBottom: '0.6rem', color: '#64748b', fontSize: '0.9rem', fontWeight: '500' }}>Original Price (₹)</label>
                              <input 
                                type="number" required
                                value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})}
                                style={inputStyle}
                              />
                          </div>
                          <div>
                              <label style={{ display: 'block', marginBottom: '0.6rem', color: '#64748b', fontSize: '0.9rem', fontWeight: '500' }}>Discounted Price (₹)</label>
                              <input 
                                type="number" required
                                value={formData.discount_price} onChange={e => setFormData({...formData, discount_price: e.target.value})}
                                style={inputStyle}
                              />
                          </div>
                      </div>

                      <div>
                          <label style={{ display: 'block', marginBottom: '0.6rem', color: '#64748b', fontSize: '0.9rem', fontWeight: '500' }}>Description (Optional)</label>
                          <textarea 
                            rows="3"
                            value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})}
                            style={{ ...inputStyle, resize: 'vertical' }}
                          />
                      </div>

                      <button className="btn" style={{ 
                          marginTop: '1rem', padding: '1rem', 
                          background: 'linear-gradient(135deg, #00d2d3 0%, #2e86de 100%)', 
                          color: '#fff', border: 'none', fontSize: '1rem', fontWeight: '600',
                          boxShadow: '0 4px 15px rgba(0, 210, 211, 0.3)',
                          cursor: 'pointer', borderRadius: '12px'
                      }}>
                          Add Service
                      </button>

                  </form>
              </div>
          </div>
      );
  }

  return (
    <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2.5rem' }}>
            <div>
                <h1 style={{ fontSize: '2rem', fontWeight: '800', color: '#1C1C24' }}>Service Management</h1>
                <p style={{ color: '#94a3b8', marginTop: '0.5rem' }}>Configure medical services and pricing.</p>
            </div>
            <button className="btn" onClick={() => setShowForm(true)} style={{ 
                background: 'linear-gradient(135deg, #00d2d3 0%, #2e86de 100%)', 
                color: '#fff', border: 'none', boxShadow: '0 4px 12px rgba(0, 210, 211, 0.3)',
                padding: '0.8rem 1.5rem', cursor: 'pointer', borderRadius: '12px',
                display: 'flex', alignItems: 'center', fontWeight: '600'
            }}>
                <Plus size={20} style={{ marginRight: '8px' }} /> Add Service
            </button>
        </div>

        {/* Filters */}
        <div style={{ ...cardStyle, padding: '1rem', display: 'flex', gap: '1rem', marginBottom: '2rem', alignItems: 'center' }}>
            <Search size={20} style={{ color: '#9CA3AF' }} />
            <input 
                type="text" placeholder="Search services..." 
                style={{ background: 'transparent', border: 'none', color: '#333', flex: 1, outline: 'none', fontSize: '0.95rem' }} 
            />
            <div style={{ width: '1px', height: '24px', background: '#E5E7EB' }}></div>
            <button style={{ background: 'transparent', border: 'none', color: '#6B7280', display: 'flex', gap: '6px', cursor: 'pointer', fontSize: '0.9rem', fontWeight: '500' }}>
                <Filter size={18} /> Filter
            </button>
        </div>

        {/* Table */}
        <div style={{ ...cardStyle, padding: '0', overflow: 'hidden' }}>
            <div style={{ overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                    <thead>
                        <tr style={{ borderBottom: '1px solid #f0f0f0', background: '#F9FAFB' }}>
                            <th style={{ padding: '1.2rem 1.5rem', color: '#9CA3AF', fontWeight: '600', fontSize: '0.8rem', textTransform: 'uppercase' }}>Service Name</th>
                            <th style={{ padding: '1.2rem 1.5rem', color: '#9CA3AF', fontWeight: '600', fontSize: '0.8rem', textTransform: 'uppercase' }}>Category</th>
                            <th style={{ padding: '1.2rem 1.5rem', color: '#9CA3AF', fontWeight: '600', fontSize: '0.8rem', textTransform: 'uppercase' }}>Hospital</th>
                            <th style={{ padding: '1.2rem 1.5rem', color: '#9CA3AF', fontWeight: '600', fontSize: '0.8rem', textTransform: 'uppercase' }}>Price</th>
                            <th style={{ padding: '1.2rem 1.5rem', color: '#9CA3AF', fontWeight: '600', fontSize: '0.8rem', textTransform: 'uppercase' }}>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {services.map((service) => (
                            <tr key={service.id} style={{ borderBottom: '1px solid #f0f0f0', transition: 'background 0.2s' }} className="hover:bg-gray-50">
                                <td style={{ padding: '1.2rem 1.5rem' }}>
                                    <div style={{ fontWeight: '600', fontSize: '1rem', marginBottom: '4px', color: '#111827' }}>{service.name}</div>
                                    <div style={{ fontSize: '0.85rem', color: '#6B7280' }}>{service.description}</div>
                                </td>
                                <td style={{ padding: '1.2rem 1.5rem' }}>
                                    <span style={{ 
                                        padding: '5px 12px', borderRadius: '20px', fontSize: '0.8rem',
                                        background: service.category === 'Lab' ? '#e0f2fe' : '#f3e8ff',
                                        color: service.category === 'Lab' ? '#0284c7' : '#9333ea',
                                        border: service.category === 'Lab' ? '1px solid #bae6fd' : '1px solid #e9d5ff',
                                        fontWeight: '500'
                                    }}>
                                        {service.category}
                                    </span>
                                </td>
                                <td style={{ padding: '1.2rem 1.5rem' }}>
                                    {service.hospital_name ? (
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#374151' }}>
                                            <Building2 size={16} color="#6B7280" /> {service.hospital_name}
                                        </div>
                                    ) : (
                                        <span style={{ color: '#9CA3AF', fontStyle: 'italic', fontSize: '0.9rem' }}>Platform Wide</span>
                                    )}
                                </td>
                                <td style={{ padding: '1.2rem 1.5rem' }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                                        <span style={{ textDecoration: 'line-through', color: '#9CA3AF', fontSize: '0.9rem' }}>₹{service.price}</span>
                                        <span style={{ color: '#00d2d3', fontWeight: 'bold', fontSize: '1.1rem' }}>₹{service.discount_price}</span>
                                    </div>
                                </td>
                                <td style={{ padding: '1.2rem 1.5rem' }}>
                                    <button className="btn-link" style={{ color: '#f87171', fontSize: '0.9rem', fontWeight: '500', background: 'transparent', border: 'none', cursor: 'pointer' }}>Delete</button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                {services.length === 0 && !loading && (
                    <div style={{ padding: '5rem', textAlign: 'center', color: '#64748b' }}>
                        <div style={{ background: '#F9FAFB', width: '70px', height: '70px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem' }}>
                           <Stethoscope size={32} style={{ opacity: 0.5, color: '#9CA3AF' }} />
                        </div>
                        <h3>No services found.</h3>
                        <p>Add one to get started.</p>
                    </div>
                )}
                
                {/* Pagination Controls */}
                {services.length > 0 && totalPages > 1 && (
                    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '1rem', padding: '1.5rem', borderTop: '1px solid #f0f0f0' }}>
                        <button 
                            disabled={page === 1}
                            onClick={() => setPage(p => Math.max(1, p - 1))}
                            className="btn"
                            style={{ 
                                background: '#F9FAFB', 
                                border: '1px solid #E5E7EB', 
                                color: page === 1 ? '#9CA3AF' : '#374151',
                                cursor: page === 1 ? 'not-allowed' : 'pointer',
                                padding: '8px 16px', borderRadius: '8px'
                            }}
                        >
                            Previous
                        </button>
                        <span style={{ color: '#6B7280', fontSize: '0.9rem' }}>Page {page} of {totalPages}</span>
                        <button 
                            disabled={page === totalPages}
                            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                            className="btn"
                            style={{ 
                                background: '#F9FAFB', 
                                border: '1px solid #E5E7EB', 
                                color: page === totalPages ? '#9CA3AF' : '#374151',
                                cursor: page === totalPages ? 'not-allowed' : 'pointer',
                                padding: '8px 16px', borderRadius: '8px'
                            }}
                        >
                            Next
                        </button>
                    </div>
                )}
            </div>
        </div>
    </div>
  );
}
